@Polynomial.coeff_X_pow : ∀ {R : Type u_1} [inst : Semiring R] (k n : ℕ),
  (Polynomial.X ^ k).coeff n = if n = k then 1 else 0
@Polynomial.coeff_X_pow_mul' : ∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n d : ℕ),
  (Polynomial.X ^ n * p).coeff d = if n ≤ d then p.coeff (d - n) else 0
@Polynomial.coeff_X_mul : ∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),
  (Polynomial.X * p).coeff (n + 1) = p.coeff n
@Polynomial.coeff_X_mul_zero : ∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R), (Polynomial.X * p).coeff 0 = 0
@add_pow_char_pow : ∀ {R : Type u_1} [inst : CommSemiring R] (x y : R) (p n : ℕ) [hp : Fact (Nat.Prime p)] [CharP R p],
  (x + y) ^ p ^ n = x ^ p ^ n + y ^ p ^ n
@Nat.lt_two_pow_self : ∀ {n : ℕ}, n < 2 ^ n

